CREATE COLUMN TABLE "TEST_AP"."OSQR" ("IntrnalKey" INTEGER CS_INT NOT NULL , "QCategory" INTEGER CS_INT, "QName" NVARCHAR(100) NOT NULL , "QString" NCLOB MEMORY THRESHOLD 1000, "QType" NVARCHAR(1) DEFAULT 'R', "ColumnSize" NVARCHAR(100), "DBType" INTEGER CS_INT, PRIMARY KEY ("IntrnalKey")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OSQR_QNAME_K" ON "TEST_AP"."OSQR" ( "QName" ASC )